"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["89267"],{80500(e){e.exports=JSON.parse('{"id":"F068","slug":"net-change-in-cash","name":"Net Change in Cash","subject":"Finance Foundations","section":"Accounting Basics","topic":"Cash flow statement","level":"Beginner","aliases":["cash flow statement total","cash flow from operations investing financing","ending cash"],"formula":{"latex":"\\\\Delta\\\\text{Cash}=CFO+CFI+CFF,\\\\quad \\\\text{Cash}_{end}=\\\\text{Cash}_{begin}+\\\\Delta\\\\text{Cash}","also":[],"text":"Change in cash = CFO + CFI + CFF, and Ending cash = Beginning cash + Change in cash"},"symbols":[{"symbol":"CFO","meaning":"Cash flow from operating activities, cash from running the business","unit":"money"},{"symbol":"CFI","meaning":"Cash flow from investing activities, usually negative when buying assets","unit":"money"},{"symbol":"CFF","meaning":"Cash flow from financing activities, such as borrowing, repaying and paying dividends","unit":"money"},{"symbol":"Cash_begin","meaning":"Cash at the start of the period","unit":"money"}],"when_to_use":"Use it to reconcile the cash flow statement. The three sections add up to the change in the cash balance on the balance sheet.","worked_example":{"problem":"A company generated 900 from operations, spent 500 on investing, and paid out 200 through financing. It began the year with 300 of cash. What is its ending cash?","inputs":{"cfo":900,"cfi":-500,"cff":-200,"begin":300},"steps":[{"label":"Net change = CFO + CFI + CFF","working":"900+-500+-200","value":"200.00"},{"label":"Ending cash = beginning cash + net change","working":"300+200","value":"500.00"}],"answer":"The net change in cash is 200.00, so ending cash is 500.00."},"calculator":{"available":true,"inputs":[{"id":"cfo","label":"Operating cash flow","unit":"money","type":"number","default":900,"hint":""},{"id":"cfi","label":"Investing cash flow","unit":"money","type":"number","default":-500,"hint":"Enter cash spent as a negative number."},{"id":"cff","label":"Financing cash flow","unit":"money","type":"number","default":-200,"hint":"Enter cash paid out as a negative number."},{"id":"begin","label":"Beginning cash","unit":"money","type":"number","default":300,"hint":""}],"checks":[],"steps":[{"id":"change","label":"Net change = CFO + CFI + CFF","expr":"cfo+cfi+cff","format":"money"},{"id":"end","label":"Ending cash = beginning cash + net change","expr":"begin+change","format":"money"}],"results":["change","end"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"change":200,"end":500}},"finder":{"finds":"How cash moved over the period","needs":"Three cash flow totals, beginning cash"},"related":[{"slug":"net-income","name":"Net Income"},{"slug":"retained-earnings","name":"Retained Earnings Roll-Forward"}],"related_ids":["F065","F069"],"group":"Foundations","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi mathvariant=\\"normal\\">\u0394</mi><mtext>Cash</mtext><mo>=</mo><mi>C</mi><mi>F</mi><mi>O</mi><mo>+</mo><mi>C</mi><mi>F</mi><mi>I</mi><mo>+</mo><mi>C</mi><mi>F</mi><mi>F</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msub><mtext>Cash</mtext><mrow><mi>e</mi><mi>n</mi><mi>d</mi></mrow></msub><mo>=</mo><msub><mtext>Cash</mtext><mrow><mi>b</mi><mi>e</mi><mi>g</mi><mi>i</mi><mi>n</mi></mrow></msub><mo>+</mo><mi mathvariant=\\"normal\\">\u0394</mi><mtext>Cash</mtext></mrow><annotation encoding=\\"application/x-tex\\">\\\\Delta\\\\text{Cash}=CFO+CFI+CFF,\\\\quad \\\\text{Cash}_{end}=\\\\text{Cash}_{begin}+\\\\Delta\\\\text{Cash}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"net-book-value","name":"Net Book Value"},"next":{"slug":"net-income","name":"Net Income"},"lesson":null,"total":522}')}}]);